CREATE TABLE product_jobs(id text PRIMARY KEY,actor_id text NOT NULL REFERENCES principals(id),credential_id text NOT NULL REFERENCES credentials(id),space_id text NOT NULL REFERENCES knowledge_spaces(id),kind text NOT NULL CHECK(kind IN ('compile','answer')),request jsonb NOT NULL,snapshot jsonb NOT NULL,status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','succeeded','failed','cancelled')),version integer NOT NULL DEFAULT 1,cancel_requested boolean NOT NULL DEFAULT false,attempt integer NOT NULL DEFAULT 0,dispatched boolean NOT NULL DEFAULT false,lease_token text,lease_until timestamptz,result jsonb,error_code text,event_seq integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE product_job_events(job_id text NOT NULL REFERENCES product_jobs(id),sequence integer NOT NULL,type text NOT NULL,time timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(job_id,sequence));
CREATE INDEX product_job_queue ON product_jobs(created_at,id) WHERE status='queued';
CREATE INDEX product_job_owner ON product_jobs(actor_id,space_id,created_at,id);
